-- Errata reading for M12: Roster age_reported as captured at profile capture (not updated by later reported-age confirmations).
WITH r AS MATERIALIZED (SELECT patient, payload FROM records WHERE stream='demographic_updates'), du AS (SELECT patient, json_extract(payload,'$.age_reported') a, json_extract(payload,'$.event_date') ed FROM r), age AS (SELECT p.id patient, json_extract(p.payload,'$.age_reported') a FROM patients p) SELECT CASE WHEN a<18 THEN '0-17' WHEN a<45 THEN '18-44' WHEN a<65 THEN '45-64' ELSE '65+' END AS age_band, COUNT(*) AS patients FROM age GROUP BY 1 ORDER BY 1;
